#!/usr/bin/env node
/* tools/apply_mobile_nucleus.mjs — v5.5 MOBILE NUCLEUS · 2026-09-23
 *
 *   sickleswarm 0.33.0: VIEW (close/normal/far/wide, #zoom #fov) · camera holds
 *   while a hand is the nucleus · the gather spreads with trust (#reach, 60) ·
 *   host: panel scrolls on a phone, VIEW dropdown, phones start at far.
 *   No WGSL changed. Starting state: main at the v5.4 landing (d8df393 + notes).
 *
 * SAFETY: every file is replaced WHOLE, only from the known starting state.
 * Any other state: nothing is written. Re-running skips what is installed.
 *
 *   node tools/apply_mobile_nucleus.mjs --dry-run
 *   node tools/apply_mobile_nucleus.mjs
 */
import fs from "node:fs"; import crypto from "node:crypto"; import path from "node:path";
const DRY = process.argv.includes("--dry-run");
const sha = (b) => crypto.createHash("sha256").update(b).digest("hex");
const P = JSON.parse("[{\"file\": \"species/sickleswarm.js\", \"target\": \"2516f737cbb72037cdabccf40acad11fcc067afd9f50b13ba3678f44a8b39f2c\", \"bases\": [\"36252fb40f51de051eefcf5c9794630787b780ad8bf9ccacde9eddd37f1fae34\"], \"b64\": \"\"}, {\"file\": \"zigverse_engine.html\", \"target\": \"8577ed1f18971c52c845aed123e08e02fdb72a3dab4f2981a3dd515152615d99\", \"bases\": [\"67ba4902ffeb8997aa3b1c5f9dd5ccea1bba7dbe4290e6d969bc24843b1e5432\"], \"b64\": \"\"}, {\"file\": \"test/_touchboot.mjs\", \"target\": \"17de6d3eda7b7dc6180c87229c9938f3246da5614ddfc52cdde28e323e703c09\", \"bases\": [\"5269fe3138d96b292b845ec2eef4be03454514f4b7ad2c402ccab7e9ea20afd7\"], \"b64\": \"\"}, {\"file\": \"test/mobile_ref.mjs\", \"target\": \"dbf1510d0efca910d46a78e89269c0deb36c10a4c69ee30eced2616234724e6d\", \"bases\": [\"ABSENT\"], \"b64\": \"\"}]");
const LOG_ENTRY = Buffer.from("", "base64");
const LOG_MARK = "v5.5 MOBILE NUCLEUS";
console.log("apply_mobile_nucleus.mjs\n");
if (!fs.existsSync("species/sickleswarm.js") || !fs.existsSync("briefs/Session_Log.md")) {
  console.log("  FAIL  run this from the repo root (C:\\Users\\billy\\Zigverse)"); process.exit(1); }
let bad = 0; const plan = [];
for (const e of P) {
  const cur = fs.existsSync(e.file) ? fs.readFileSync(e.file) : null;
  /* Git on Windows may turn LF into CRLF when it touches a file — the same
     text, different bytes. Compare both ways so a clean folder is never refused. */
  const lf = cur ? sha(Buffer.from(cur.toString("utf8").replace(/\r\n/g, "\n"), "utf8")) : "ABSENT";
  const h = cur ? (e.bases.includes(lf) || lf === e.target ? lf : sha(cur)) : "ABSENT";
  if (h === e.target) { console.log("  SKIP  " + e.file.padEnd(26) + " already installed"); continue; }
  if (!e.bases.includes(h)) { console.log("  FAIL  " + e.file.padEnd(26) + " unrecognised state (" + h.slice(0, 12) + ") — local edits?"); bad++; continue; }
  const out = Buffer.from(e.b64, "base64");
  if (sha(out) !== e.target) { console.log("  FAIL  " + e.file + " payload corrupt"); bad++; continue; }
  plan.push([e.file, out]); console.log("  OK    " + e.file.padEnd(26) + (cur ? " recognised → will replace" : " new file"));
}
const log = fs.readFileSync("briefs/Session_Log.md", "utf8");
const needLog = !log.includes(LOG_MARK);
console.log("  " + (needLog ? "OK    briefs/Session_Log.md       entry will be appended" : "SKIP  briefs/Session_Log.md       entry already present"));
if (bad) { console.log("\n  Nothing written. " + bad + " file(s) not in a state this installer knows."); process.exit(1); }
if (DRY) { console.log("\n  DRY RUN — all checks pass, nothing written."); process.exit(0); }
for (const [f, out] of plan) {
  fs.mkdirSync(path.dirname(f), { recursive: true });
  fs.writeFileSync(f, out);
  if (sha(fs.readFileSync(f)) !== sha(out)) { console.log("  FAIL  write verify " + f); process.exit(1); }
  console.log("  WROTE " + f + "  sha256 " + sha(out).slice(0, 16) + "… verified");
}
if (needLog) { fs.appendFileSync("briefs/Session_Log.md", LOG_ENTRY); console.log("  WROTE briefs/Session_Log.md (appended)"); }
console.log("\n  NEXT (Bill, eyeZ, PowerShell):");
console.log("    reference checks (expect 50 PASS), bundle to dist\\Zigverse_Engine_v5_5_Mobile.html,");
console.log("    boot_gate, node test\\_touchboot.mjs, then LAND.cmd — Glyph gives the lines.");
